<?php

namespace App\Services;

use App\Models\Team;
use Carbon\Carbon;
use InvalidArgumentException;
use Laravel\Cashier\Cashier;
use Stripe\Exception\ApiErrorException;

/**
 * Schedules a monthly subscription to become annual at the end of the current
 * billing period.
 *
 * The annual invoice is generated by Stripe at the renewal date, so the
 * customer is not charged today and the 20 % coupon is applied to the first
 * full annual invoice.
 */
class ScheduledPlanChangeService
{
    public function __construct(
        private readonly PlanCatalog $catalog,
        private readonly BlackFridayPromotion $promotion,
    ) {}

    public function estimatedChangeAt(Team $team): ?Carbon
    {
        $subscription = $team->subscription('default');

        if (! $subscription) {
            return null;
        }

        $stripeSubscription = $subscription->asStripeSubscription();
        $periodEnd = $stripeSubscription->current_period_end
            ?? $stripeSubscription->items->data[0]->current_period_end
            ?? null;

        return $periodEnd ? Carbon::createFromTimestamp($periodEnd) : null;
    }

    public function schedule(Team $team, string $tier): void
    {
        if (! $this->promotion->canScheduleUpgrade($team, $tier)) {
            throw new InvalidArgumentException('The annual upgrade is not available for this subscription.');
        }

        $subscription = $team->subscription('default');
        $coupon = $this->promotion->annualCoupon();

        if (! $subscription || ! $coupon) {
            throw new InvalidArgumentException('The annual coupon is not configured.');
        }

        $annualPriceId = $this->catalog->priceId($tier, 'annual');

        $schedule = Cashier::stripe()->subscriptionSchedules->create([
            'from_subscription' => $subscription->stripe_id,
        ]);

        if (count($schedule->phases) !== 1) {
            throw new InvalidArgumentException('This subscription already has a scheduled change.');
        }

        $currentPhase = $schedule->phases[0];

        if (count($currentPhase->discounts ?? []) > 0) {
            throw new InvalidArgumentException('Subscriptions with an existing discount must be changed from the billing portal.');
        }

        $currentItem = $currentPhase->items[0];
        $currentPriceId = is_string($currentItem->price)
            ? $currentItem->price
            : $currentItem->price->id;
        $periodEnd = (int) $currentPhase->end_date;

        try {
            Cashier::stripe()->subscriptionSchedules->update($schedule->id, [
                'end_behavior' => 'release',
                'phases' => [
                    [
                        'items' => [
                            ['price' => $currentPriceId, 'quantity' => 1],
                        ],
                        'start_date' => (int) $currentPhase->start_date,
                        'end_date' => $periodEnd,
                        'proration_behavior' => 'none',
                    ],
                    [
                        'items' => [
                            ['price' => $annualPriceId, 'quantity' => 1],
                        ],
                        'start_date' => $periodEnd,
                        'duration' => [
                            'interval' => 'year',
                            'interval_count' => 1,
                        ],
                        'proration_behavior' => 'none',
                        'discounts' => [
                            ['coupon' => $coupon],
                        ],
                    ],
                ],
            ]);
        } catch (ApiErrorException $exception) {
            // Do not leave an accidental single-phase schedule attached when
            // the phase update fails.
            try {
                Cashier::stripe()->subscriptionSchedules->release($schedule->id);
            } catch (ApiErrorException) {
                // Best effort only; the original failure is more useful.
            }

            throw $exception;
        }

        $subscription->forceFill([
            'stripe_schedule_id' => $schedule->id,
            'scheduled_tier' => $tier,
            'scheduled_price_id' => $annualPriceId,
            'scheduled_change_at' => Carbon::createFromTimestamp($periodEnd),
        ])->save();
    }

    public function cancel(Team $team): void
    {
        $subscription = $team->subscription('default');

        if (! $subscription || ! $subscription->stripe_schedule_id) {
            return;
        }

        try {
            Cashier::stripe()->subscriptionSchedules->release($subscription->stripe_schedule_id);
        } finally {
            $subscription->forceFill([
                'stripe_schedule_id' => null,
                'scheduled_tier' => null,
                'scheduled_price_id' => null,
                'scheduled_change_at' => null,
            ])->save();
        }
    }

    /**
     * @return array{date: Carbon, tier: string|null, price: string|null}|null
     */
    public function scheduledChange(Team $team): ?array
    {
        $subscription = $team->subscription('default');

        if (! $subscription?->scheduled_change_at) {
            return null;
        }

        return [
            'date' => $subscription->scheduled_change_at,
            'tier' => $subscription->scheduled_tier,
            'price' => $subscription->scheduled_price_id,
        ];
    }
}
